// Business & Client Directory
const PRACTICES = {
  'mr-khan-automations': {
    id: 'mr-khan-automations',
    name: 'MR Khan Automation Services',
    services: 'Custom n8n Workflow Automations, AI Voice Receptionists, Lead Generation Pipelines',
    website: 'https://portfolio.mrkhan.qzz.io',
    phone: '+1 (737) 238-2376',
    hours: 'Mon-Fri 9am-6pm',
    bookingPolicy: 'Free 30-minute AI Strategy & Discovery Call.'
  },
  'the-cosmetic-dentists-of-austin': {
    id: 'the-cosmetic-dentists-of-austin',
    name: 'The Cosmetic Dentists of Austin',
    doctors: 'Dr. John M. Hay, DDS & Dr. John C. Schiro, DDS',
    services: 'Porcelain Veneers, Smile Makeovers, Full Mouth Reconstruction',
    phone: '(512) 333-7777',
    dedicatedVoiceNumber: '+1 (737) 238-2376',
    address: '2700 Barton Creek Blvd Suite 130, Austin, TX 78735',
    hours: 'Mon-Thu 9am-5pm, Fri 9am-1:30pm, Sat-Sun Closed',
    calendarId: 'primary',
    financing: 'Flexible financing available starting at $250/month. Last Time You Pay Policy.',
    bookingPolicy: 'Complimentary in-person or virtual cosmetic consultations.'
  },
  'austin-dental-spa': {
    id: 'austin-dental-spa',
    name: 'Austin Dental Spa',
    doctors: 'Dr. Mark Sweeney & Dr. Krista Froehlich',
    services: 'Cosmetic Dentistry, Veneers, Invisalign, Sedation Dentistry',
    phone: '(512) 452-9296',
    address: '3305 Northland Dr #515, Austin, TX 78731',
    hours: 'Mon-Wed 8am-5pm, Thu 7am-2pm, Fri-Sun Closed',
    calendarId: 'primary',
    financing: 'Custom payment plans and CareCredit accepted.',
    bookingPolicy: 'Full consultation with digital smile imaging.'
  },
  'austin-med-spa': {
    id: 'austin-med-spa',
    name: 'Austin Med Spa',
    doctors: 'Medical Aesthetic Director & Senior Injectors',
    services: 'Botox, Dermal Fillers, Hydrafacial, Emsculpt, Pico Laser',
    phone: '(512) 479-9997',
    address: '1611 W 6th St, Austin, TX 78703',
    hours: 'Mon-Fri 9am-5pm, Sat-Sun Closed',
    calendarId: 'primary',
    financing: 'Membership discounts and Cherry financing available.',
    bookingPolicy: 'Personalized aesthetic assessment.'
  }
};

const payload = $input.first().json.body || $input.first().json;
const message = payload.message || payload;
const msgType = message.type || '';

let action = 'ignore';
let resolvedClientId = 'mr-khan-automations';
let toolCallId = null;
let toolArgs = {};
let ragQuery = '';
let reqDate = '';
let reqTime = '';
let clientPhone = '';

if (msgType === 'assistant-request') {
  action = 'assistant_request';
  resolvedClientId = 'mr-khan-automations';
} else if (msgType === 'tool-calls') {
  const toolCall = message.toolCalls?.[0] || {};
  toolCallId = toolCall.id || 'tc_default';
  const toolName = toolCall.function?.name || 'book_appointment';
  try {
    toolArgs = typeof toolCall.function?.arguments === 'string' 
      ? JSON.parse(toolCall.function.arguments) 
      : (toolCall.function?.arguments || {});
  } catch (e) {
    toolArgs = {};
  }

  const rawClientId = (toolArgs.client_id || '').toLowerCase();
  if (rawClientId.includes('dental spa') || rawClientId.includes('austin-dental-spa')) resolvedClientId = 'austin-dental-spa';
  else if (rawClientId.includes('med spa') || rawClientId.includes('austin-med-spa')) resolvedClientId = 'austin-med-spa';
  else if (rawClientId.includes('cosmetic dentists')) resolvedClientId = 'the-cosmetic-dentists-of-austin';
  else resolvedClientId = 'mr-khan-automations';

  if (toolName === 'query_knowledge_base' || toolName === 'search_company_info') {
    action = 'query_knowledge_base';
    ragQuery = toolArgs.query || toolArgs.question || toolArgs.topic || 'What services do you offer?';
  } else if (toolName === 'check_availability') {
    action = 'check_availability';
    reqDate = toolArgs.requested_date || toolArgs.preferred_date || '';
    reqTime = toolArgs.requested_time || toolArgs.preferred_time || '';
  } else if (toolName === 'cancel_appointment') {
    action = 'cancel_appointment';
    clientPhone = toolArgs.client_phone || toolArgs.phone || '';
  } else {
    action = 'book_appointment';
  }
} else if (msgType === 'end-of-call-report') {
  action = 'end_of_call';
  resolvedClientId = 'mr-khan-automations';
} else if (!msgType && payload.toolCalls) {
  const toolCall = payload.toolCalls[0] || {};
  toolCallId = toolCall.id || 'tc_test';
  const toolName = toolCall.function?.name;
  toolArgs = toolCall.function?.arguments || {};
  if (toolName === 'query_knowledge_base') {
    action = 'query_knowledge_base';
    ragQuery = toolArgs.query || 'What services do you offer?';
  } else if (toolName === 'check_availability') {
    action = 'check_availability';
    reqDate = toolArgs.requested_date || '';
    reqTime = toolArgs.requested_time || '';
  } else if (toolName === 'cancel_appointment') {
    action = 'cancel_appointment';
    clientPhone = toolArgs.client_phone || '';
  } else {
    action = 'book_appointment';
  }
} else {
  action = 'ignore';
}

const practice = PRACTICES[resolvedClientId] || PRACTICES['mr-khan-automations'];
const pName = toolArgs.patient_name || toolArgs.client_name || 'Prospective Client';
const cleanPhone = (toolArgs.client_phone || toolArgs.patient_phone || toolArgs.phone || clientPhone || '+1-512-555-0100').replace(/^'+/, '');
const pEmail = toolArgs.patient_email || toolArgs.email || 'client@example.com';
const pService = toolArgs.requested_service || toolArgs.service || 'AI Strategy & Discovery Call';
const pStart = toolArgs.appointment_time || new Date(Date.now() + 86400000 * 2).toISOString();
const pNotes = toolArgs.patient_notes || toolArgs.notes || 'Booked via MR Khan AI Voice Assistant';
const nowStr = new Date().toISOString();

let pEnd = '';
try {
  const parsedDate = new Date(pStart);
  if (!isNaN(parsedDate.getTime())) {
    pEnd = new Date(parsedDate.getTime() + 1800000).toISOString();
  } else {
    pEnd = pStart;
  }
} catch (e) {
  pEnd = pStart;
}

return [{
  json: {
    action,
    toolCallId,
    rag_query: ragQuery,
    requested_date: reqDate,
    requested_time: reqTime,
    cancel_phone: cleanPhone,
    practice,
    patient_name: pName,
    patient_phone: cleanPhone,
    patient_email: pEmail,
    requested_service: pService,
    appointment_start: pStart,
    appointment_end: pEnd,
    patient_notes: pNotes,
    callSummary: message.summary || 'Call completed with strategy session booked.',
    recordingUrl: message.recordingUrl || 'https://vapi.ai/recordings/sample',
    'Practice Name': practice.name,
    'Client Name': pName,
    'Phone Number': cleanPhone,
    'Email Address': pEmail,
    'Requested Service': pService,
    'Scheduled Time': pStart,
    'Status': action === 'cancel_appointment' ? 'CANCELLED' : 'CONFIRMED',
    'Notes / Goals': action === 'cancel_appointment' ? 'Cancelled by client via Voice Assistant' : pNotes,
    'Booked At': nowStr,
    'Patient Name': pName,
    'Patient Phone': cleanPhone,
    'Patient Email': pEmail,
    'Patient Notes': pNotes
  }
}];

const parserJson = $input.first().json;
const toolCallId = parserJson.toolCallId || 'tc_avail';
const reqDate = (parserJson.requested_date || '').toLowerCase().trim();
const reqTime = (parserJson.requested_time || '').toLowerCase().trim();
const practice = parserJson.practice;

// 1. Weekend Constraint Check
if (reqDate.includes('sat') || reqDate.includes('sun') || reqDate.includes('saturday') || reqDate.includes('sunday')) {
  return [{
    json: {
      vapiResponse: {
        results: [{
          toolCallId: toolCallId,
          result: "We are closed on weekends. Our consultation hours are Monday through Friday, 9:00 AM to 6:00 PM. Would Monday morning or Tuesday afternoon work for you?"
        }]
      }
    }
  }];
}

// 2. Specific Day + Time Slot Check
let message = '';
if (reqDate && reqTime) {
  const capDate = reqDate.charAt(0).toUpperCase() + reqDate.slice(1);
  message = `Yes! ${capDate} at ${reqTime} is open for your 30-minute AI strategy consultation. May I have your first and last name to reserve this for you?`;
} else if (reqDate) {
  const capDate = reqDate.charAt(0).toUpperCase() + reqDate.slice(1);
  message = `For ${capDate}, we have open consultation slots at 10:30 AM, 2:00 PM, and 4:30 PM. Which of those works best for you?`;
} else {
  message = "We have open 30-minute consultation slots this week on Tuesday at 2:00 PM, Wednesday at 10:30 AM, and Thursday at 3:00 PM. We can also accommodate any weekday between 9 AM and 6 PM. What day and time works best for you?";
}

return [{
  json: {
    vapiResponse: {
      results: [{
        toolCallId: toolCallId,
        result: message
      }]
    }
  }
}];
